function resolveInstitutionSlug(){const p=new URLSearchParams(window.location.search);const q=normalizeSlug(p.get('institution'));if(q)return q;const parts=window.location.pathname.split('/').filter(Boolean);if(!parts.length)return DEFAULT_INSTITUTION_SLUG;const last=parts[parts.length-1];if(last==='admin.html'||last==='index.html')return normalizeSlug(parts[parts.length-2])||DEFAULT_INSTITUTION_SLUG;if(last==='app'||last==='landing'||last==='landing.html')return DEFAULT_INSTITUTION_SLUG;return normalizeSlug(last)||DEFAULT_INSTITUTION_SLUG;}
function resolveStrategySlug(){const p=new URLSearchParams(window.location.search);return normalizeSlug(p.get('strategy'));}
function normalizeSlug(v){const s=String(v||'').trim().toLowerCase();return s&&/^[a-z0-9-]+$/.test(s)?s:'';}
function mountAdminApp(options={}){const nextRoot=options.root||document.getElementById('adminRoot');if(!nextRoot)return false;root=nextRoot;const nextSlug=normalizeSlug(options.institutionSlug);const nextStrategySlug=normalizeSlug(options.strategySlug);if((nextSlug&&nextSlug!==state.institutionSlug)||(nextStrategySlug!==state.strategySlug)){if(nextSlug)state.institutionSlug=nextSlug;state.strategySlug=nextStrategySlug;state.strategy=null;state.strategies=[];state.error='';state.notice='';state.context=null;state.cycle=null;state.participants=[];state.guidelines=[];state.initiatives=[];state.availableGuidelines=[];state.parentGuidelines=[];state.guidelineLinks=[];state.pendingProposals=[];state.pendingReviewProposalId='';state.inviteToken='';state.inviteUrl='';state.inviteExpiresAt=null;state.lastPasswordReset=null;state.embedViewStats={viewCount:0,lastViewedAt:null,totalEmbedViews:0};state.itPlanDraftOverrides={};}if(options.forceAuthSync)hydrateAuthFromStorage();bootstrap();return true;}
window.DigiAdminApp={mount:mountAdminApp};

function hydrateAuthFromStorage(){const raw=localStorage.getItem(AUTH_STORAGE_KEY);if(!raw)return;try{const p=JSON.parse(raw);if(!p?.token)return;state.token=p.token;state.user=p.user||null;state.role=p.role||null;}catch{localStorage.removeItem(AUTH_STORAGE_KEY);}}
function persistAuthToStorage(){if(!state.token){localStorage.removeItem(AUTH_STORAGE_KEY);return;}localStorage.setItem(AUTH_STORAGE_KEY,JSON.stringify({slug:state.institutionSlug,homeSlug:state.institutionSlug,token:state.token,user:state.user,role:state.role}));}
function clearSession(){state.token=null;state.user=null;state.role=null;state.context=null;state.cycle=null;localStorage.removeItem(AUTH_STORAGE_KEY);window.dispatchEvent(new CustomEvent('uzt-auth-changed'));}
function setSession(payload){state.token=payload.token||null;state.user=payload.user||null;state.role=payload.role||null;persistAuthToStorage();window.dispatchEvent(new CustomEvent('uzt-auth-changed'));}

let resizeRaf=0;let resizeTimer=0;
function postEmbeddedHeight(){if(!IS_EMBEDDED_ADMIN)return;const b=document.body;const d=document.documentElement;const h=Math.max(Number(b?.scrollHeight||0),Number(b?.offsetHeight||0),Number(d?.scrollHeight||0),Number(d?.offsetHeight||0));window.parent.postMessage({type:ADMIN_FRAME_HEIGHT_EVENT,height:h},'*');}
function queueEmbeddedHeightPost(){if(!IS_EMBEDDED_ADMIN)return;if(resizeRaf)window.cancelAnimationFrame(resizeRaf);resizeRaf=window.requestAnimationFrame(()=>{resizeRaf=0;postEmbeddedHeight();});}
function setupEmbeddedHeightReporter(){if(!IS_EMBEDDED_ADMIN)return;window.addEventListener('load',queueEmbeddedHeightPost);window.addEventListener('resize',queueEmbeddedHeightPost);if(document.body){const mo=new MutationObserver(queueEmbeddedHeightPost);mo.observe(document.body,{childList:true,subtree:true,attributes:true});}if(resizeTimer)window.clearInterval(resizeTimer);resizeTimer=window.setInterval(queueEmbeddedHeightPost,900);}

function escapeHtml(v){return String(v||'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');}
function normalizeKeywordList(value){const source=Array.isArray(value)?value:String(value||'').split(/[,;\n]+/);const seen=new Set();const out=[];source.forEach(item=>{const text=String(item||'').replace(/\s+/g,' ').trim();if(!text||text.length>40)return;const key=text.toLocaleLowerCase('lt-LT');if(seen.has(key))return;seen.add(key);out.push(text);});return out.slice(0,16);}
function keywordInputValue(value){return normalizeKeywordList(value).join(', ');}
function formatDateTime(v){const locale=resolveEmbedLanguage()==='en'?'en-US':'lt-LT';if(!v)return langText('Data nenurodyta','Date not provided');const d=new Date(v);if(Number.isNaN(d.getTime()))return langText('Data nenurodyta','Date not provided');return new Intl.DateTimeFormat(locale,{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(d);}
function toUserMessage(error){const raw=String(error?.message||error||'').trim();const map={unauthorized:'Reikia prisijungti kaip institucijos administratorius.','invalid token':'Sesija nebegalioja. Prisijunkite iš naujo.','institution not found':`Institucija "${state.institutionSlug}" nerasta.`,'strategy not found':'Pasirinkta strategija nerasta.','strategy title required':'Įveskite strategijos pavadinimą.','invalid strategy slug':'Netinkamas strategijos kodas (slug).','strategy slug already exists':'Šis strategijos kodas jau naudojamas.','cycle not found':'Aktyvus ciklas nerastas.',forbidden:'Veiksmas neleidžiamas.','admin role required':'Reikalingos administratoriaus teisės.','cross-institution forbidden':'Prieiga prie kitos institucijos duomenų neleidžiama.','invalid credentials':'Neteisingi prisijungimo duomenys.','email required':'Nurodykite el. paštą.','too many requests':'Per daug užklausų. Pabandykite po kelių sekundžių.','userId required':'Trūksta vartotojo ID.','user inactive':'Vartotojas neaktyvus (arba archyvuotas).','userId and password(min 8) required':'Slaptažodis turi būti bent 8 simbolių.','cannot delete self':'Negalite ištrinti savo paskyros.','membership not found':'Narystė nerasta.','invalid relation type':'Netinkamas gairės ryšio tipas.','parent guideline required for child':'Vaikinei gairei būtina parinkti tėvinę gairę.','parent guideline not found':'Tėvinė gairė nerasta.','parent must be in same cycle':'Tėvinė gairė turi būti tame pačiame cikle.','child cannot be parent of itself':'Gairė negali būti pati sau tėvinė.','parent guideline must be parent':'Pasirinkta gairė nėra tėvinė.','cannot demote parent with children':'Negalima keisti tėvinės gairės tipo, kol ji turi vaikinių gairių.','sourceGuidelineId and targetGuidelineId required':'Pasirinkite šaltinio ir tikslo tėvines gaires.','source and target must differ':'Šaltinio ir tikslo gairės turi skirtis.','parent guideline required':'Ryšiams galima naudoti tik tėvines gaires.','failed to create guideline link':'Nepavyko sukurti gairių ryšio.','guideline link not found':'Gairių ryšys nerastas.','linkId required':'Trūksta ryšio ID.','guideline not found':'Gairė nerasta.','initiative not found':'Iniciatyva nerasta.','comment not found':'Komentaras nerastas.','guideline not in cycle':'Pasirinkta gairė nepriklauso šiam ciklui.','missionText or visionText required':'Nurodykite misiją arba viziją.','at least one guideline required':'Iniciatyva turi būti priskirta bent vienai gairei.'};return map[raw]||raw||'Nepavyko įvykdyti užklausos.';}
function notifySuccess(message){const text=String(message||'').trim();if(!text)return;if(window.DigiAlerts&&typeof window.DigiAlerts.success==='function')window.DigiAlerts.success(text);}
function notifyError(message){const text=String(message||'').trim();if(!text)return;if(window.DigiAlerts&&typeof window.DigiAlerts.error==='function')window.DigiAlerts.error(text);}
function setNotice(message,type='success'){const text=String(message||'').trim();state.notice=text;if(!text)return;if(type==='error')notifyError(text);else notifySuccess(text);}

async function api(path,{method='GET',body=null,auth=true}={}){const headers={};if(body!==null)headers['Content-Type']='application/json';if(auth){if(!state.token)throw new Error('unauthorized');headers.Authorization=`Bearer ${state.token}`;}const r=await fetch(path,{method,headers,body:body!==null?JSON.stringify(body):undefined});const raw=await r.text();let payload=null;if(raw){try{payload=JSON.parse(raw);}catch{payload=null;}}if(!r.ok)throw new Error(payload?.error||`HTTP ${r.status}`);return payload||{};}

function contextPath(){const p=new URLSearchParams();const strategySlug=normalizeSlug(state.strategySlug);if(strategySlug)p.set('strategy',strategySlug);const query=p.toString();return`/api/v1/me/context${query?`?${query}`:''}`;}
function normalizeStrategyRecord(value){if(!value||typeof value!=='object')return null;const slug=normalizeSlug(value.slug);if(!slug)return null;return{id:value.id||null,title:String(value.title||slug).trim(),slug,description:String(value.description||'').trim(),status:String(value.status||'active').trim(),isDefault:Boolean(value.isDefault??value.is_default),createdAt:value.createdAt||value.created_at||null};}
async function switchInstitutionSession(){if(!state.token)return null;const slug=normalizeSlug(state.institutionSlug);if(!slug)return null;const strategySlug=normalizeSlug(state.strategySlug);return api('/api/v1/auth/switch-institution',{method:'POST',body:{institutionSlug:slug,strategySlug:strategySlug||undefined}});}
async function loadContext(){let c=await api(contextPath());if(!c?.institution?.slug)throw new Error('Nepavyko gauti konteksto.');const ctxSlug=normalizeSlug(c.institution.slug);const targetSlug=normalizeSlug(state.institutionSlug);if(targetSlug&&ctxSlug!==targetSlug){try{const switched=await switchInstitutionSession();if(switched?.token)setSession(switched);}catch{}c=await api(contextPath());}if(normalizeSlug(c?.institution?.slug)!==targetSlug){throw new Error('membership inactive');}if(String(c.membership?.status||'')!=='active')throw new Error('membership inactive');if(c.membership?.role!=='institution_admin')throw new Error('admin role required');state.context=c;state.strategies=Array.isArray(c.strategies)?c.strategies.map(normalizeStrategyRecord).filter(Boolean):[];state.strategy=normalizeStrategyRecord(c.strategy)||state.strategies.find(s=>s.isDefault)||state.strategies[0]||null;if(state.strategy?.slug)state.strategySlug=state.strategy.slug;state.cycle=c.cycle||null;state.user=state.user||c.user||null;state.role=c.membership?.role||'member';}

async function loadAdminData() {
  if (!state.cycle?.id) {
    state.participants = [];
    state.guidelines = [];
    state.initiatives = [];
    state.availableGuidelines = [];
    state.parentGuidelines = [];
    state.guidelineLinks = [];
    state.pendingProposals = [];
    state.pendingReviewProposalId = '';
    state.lastPasswordReset = null;
    state.embedViewStats = { viewCount: 0, lastViewedAt: null, totalEmbedViews: 0 };
    return;
  }
  const [pp, gp, ip, ev, pr] = await Promise.all([
    api(`/api/v1/admin/cycles/${encodeURIComponent(state.cycle.id)}/participants`),
    api(`/api/v1/admin/cycles/${encodeURIComponent(state.cycle.id)}/guidelines`),
    api(`/api/v1/admin/cycles/${encodeURIComponent(state.cycle.id)}/initiatives`),
    api('/api/v1/admin/embed-views'),
    api(`/api/v1/admin/cycles/${encodeURIComponent(state.cycle.id)}/proposals`)
  ]);
  state.participants = Array.isArray(pp.participants) ? pp.participants : [];
  state.guidelines = Array.isArray(gp.guidelines) ? gp.guidelines : [];
  state.parentGuidelines = Array.isArray(gp.parentGuidelines) ? gp.parentGuidelines : [];
  state.guidelineLinks = Array.isArray(gp.guidelineLinks) ? gp.guidelineLinks : [];
  state.initiatives = Array.isArray(ip.initiatives) ? ip.initiatives : [];
  state.pendingProposals = Array.isArray(pr.entries) ? pr.entries : [];
  state.availableGuidelines = Array.isArray(ip.guidelines) ? ip.guidelines : state.guidelines.map((g) => ({ id: g.id, title: g.title, status: g.status }));
  state.embedViewStats = { viewCount: Number(ev?.viewCount || 0), lastViewedAt: ev?.lastViewedAt || null, totalEmbedViews: Number(ev?.totalEmbedViews || 0) };
}

async function bootstrap(){root=root||document.getElementById('adminRoot');if(!root)return;if(!state.token){render();return;}state.loading=true;state.error='';render();try{await loadContext();await loadAdminData();}catch(error){state.error=toUserMessage(error);if(String(error?.message||'')==='invalid token'||String(error?.message||'')==='unauthorized')clearSession();}finally{state.loading=false;render();}}
async function runBusy(task){if(state.busy)return;state.busy=true;state.notice='';render();try{await task();}catch(error){setNotice(toUserMessage(error),'error');}finally{state.busy=false;render();}}
async function regenerateItPlanDraftFromStrategy(){if(state.busy)return;state.busy=true;state.itPlanGenerating=true;state.notice='';state.adminTab='it-plan';state.itPlanDraftOverrides={};render();try{await loadContext();await loadAdminData();state.itPlanGeneratedAt=new Date().toISOString();setNotice('IT plano juodraštis sugeneruotas pagal naujausią strategijos informaciją.');}catch(error){setNotice(toUserMessage(error),'error');}finally{state.busy=false;state.itPlanGenerating=false;render();}}
async function regenerateItPlanDraftBlockFromStrategy(blockId){const id=String(blockId||'').trim();if(state.busy||!id)return;state.busy=true;state.itPlanGeneratingBlockId=id;state.notice='';state.adminTab='it-plan';delete state.itPlanDraftOverrides[id];render();try{await loadContext();await loadAdminData();state.itPlanGeneratedAt=new Date().toISOString();setNotice('IT plano skirsnis sugeneruotas pagal naujausią strategijos informaciją.');}catch(error){setNotice(toUserMessage(error),'error');}finally{state.busy=false;state.itPlanGeneratingBlockId='';render();}}

function checkedValues(scope,name='guidelineIds'){if(!(scope instanceof Element))return[];return Array.from(scope.querySelectorAll(`input[name="${name}"]:checked`)).map(i=>String(i.value||'').trim()).filter(Boolean);}
function guidelineCheckboxes(selectedIds,name='guidelineIds',disabled=false){const sel=new Set(Array.isArray(selectedIds)?selectedIds.map(String):[]);if(!state.availableGuidelines.length)return'<p class="prompt guideline-checkbox-empty">Nėra gairių pasirinkimui.</p>';return `<div class="guideline-checkbox-list">${state.availableGuidelines.map(g=>`<label class="guideline-checkbox-item"><input class="guideline-checkbox-input" type="checkbox" name="${escapeHtml(name)}" value="${escapeHtml(g.id)}" ${sel.has(String(g.id))?'checked':''} ${disabled?'disabled':''}/><span class="guideline-checkbox-label">${escapeHtml(g.title||g.id)}</span></label>`).join('')}</div>`;}
function resolveEmbedLanguage(){const fromQuery=String(new URLSearchParams(window.location.search).get('lang')||'').trim().toLowerCase();if(fromQuery)return fromQuery==='en'?'en':'lt';const fromStorage=String(localStorage.getItem('uzt-strategy-v1-lang')||'').trim().toLowerCase();if(fromStorage)return fromStorage==='en'?'en':'lt';const fromI18n=String(window.DigiI18n?.getLanguage?.()||'').trim().toLowerCase();if(fromI18n)return fromI18n==='en'?'en':'lt';const fromHtml=String(document.documentElement?.lang||'').trim().toLowerCase();return fromHtml==='en'?'en':'lt';}
function langText(lt,en){return resolveEmbedLanguage()==='en'?en:lt;}
function buildInstitutionEmbedSourceUrl(){const slug=normalizeSlug(state.institutionSlug);if(!slug)return'';const strategySlug=normalizeSlug(state.strategySlug);const lang=resolveEmbedLanguage();const base=`${window.location.origin}${EMBED_MAP_PATH_PREFIX}/`;const params=new URLSearchParams();params.set('institution',slug);if(strategySlug)params.set('strategy',strategySlug);params.set(EMBED_QUERY_KEY,EMBED_MAP_VALUE);params.set('view','map');params.set('lang',lang);return `${base}?${params.toString()}`;}
function buildInstitutionEmbedIframeCode(){const src=buildInstitutionEmbedSourceUrl();if(!src)return'';return['<iframe',`  src="${src}"`,'  width="100%"','  height="720"','  loading="lazy"','  style="border:0;overflow:hidden;"','  referrerpolicy="strict-origin-when-cross-origin"','  allowfullscreen','></iframe>'].join('\n');}
function normalizeAiProvider(v){const s=String(v||'').trim().toLowerCase();return s==='mistral'?'mistral':'openai';}
function aiProviderLabel(v){return normalizeAiProvider(v)==='mistral'?'Mistral':'OpenAI';}
function renderCycleEmbedCard(embedCode){if(!embedCode)return'';const localViews=Number(state.embedViewStats?.viewCount||0);const embedTitle=langText('Embed: Strategijų žemėlapis (view-only)','Embed: Strategy map (view-only)');const institutionLabel=langText('Institucija','Institution');const totalLoadsLabel=langText('Viso užkrovimų','Total loads');const embedHelp=langText('Įdėkite kodą į savo svetainę. Įterptas blokas rodo tik viešus pasirinktos institucijos žemėlapio duomenis.','Add this code to your website. The embedded block displays only public strategy map data for the selected institution.');const copyEmbedCodeLabel=langText('Kopijuoti embed kodą','Copy embed code');return `<section class="card admin-embed-card" data-admin-section="cycle" style="margin-bottom:16px;"><div class="header-row"><strong>${embedTitle}</strong><span class="tag">${institutionLabel}: ${escapeHtml(state.institutionSlug)}</span></div><div class="header-stack"><span class="tag">${totalLoadsLabel}: ${localViews}</span></div><p class="prompt admin-embed-help">${embedHelp}</p><textarea id="adminEmbedCode" class="admin-embed-code" readonly>${escapeHtml(embedCode)}</textarea><div class="inline-form" style="margin-top:10px;"><button id="copyEmbedCodeBtn" class="btn btn-primary" type="button">${copyEmbedCodeLabel}</button></div></section>`;}
function buildGuidelineOpenHref(institutionSlug,strategySlug,guidelineId){const i=normalizeSlug(institutionSlug)||normalizeSlug(state.institutionSlug);const s=normalizeSlug(strategySlug)||normalizeSlug(state.strategySlug);const g=String(guidelineId||'').trim();const params=new URLSearchParams();if(i)params.set('institution',i);if(s)params.set('strategy',s);params.set('view','guidelines');if(g)params.set(FOCUS_GUIDELINE_QUERY_KEY,g);return `/index.html?${params.toString()}`;}
function guidelineCatalogLabel(item){const strategy=String(item?.strategyTitle||item?.strategySlug||'default').trim()||'default';const title=String(item?.title||'-').trim()||'-';return `${strategy} / ${title}`;}
function buildStrategicLinkRows(){const links=Array.isArray(state.guidelineLinks)?state.guidelineLinks:[];return links.map(link=>({id:String(link?.id||'').trim(),sourceGuidelineTitle:String(link?.source?.guidelineTitle||'-').trim()||'-',sourceStrategyTitle:String(link?.source?.strategyTitle||link?.source?.strategySlug||'default').trim()||'default',targetGuidelineTitle:String(link?.target?.guidelineTitle||'-').trim()||'-',targetGuidelineId:String(link?.target?.guidelineId||'').trim(),targetStrategyTitle:String(link?.target?.strategyTitle||link?.target?.strategySlug||'default').trim()||'default',targetStrategySlug:normalizeSlug(link?.target?.strategySlug)||normalizeSlug(state.strategySlug),isCrossStrategy:Boolean(link?.isCrossStrategy),createdAt:link?.createdAt||null})).filter(row=>row.id&&row.targetGuidelineId).sort((a,b)=>a.sourceGuidelineTitle.localeCompare(b.sourceGuidelineTitle,'lt'));}
function renderCycleStrategicLinksCard(){const parentGuidelines=Array.isArray(state.parentGuidelines)?state.parentGuidelines:[];const rows=buildStrategicLinkRows();const hasEnoughGuidelines=parentGuidelines.length>=2;const guidelineOptions=parentGuidelines.map(item=>`<option value="${escapeHtml(item.id)}">${escapeHtml(guidelineCatalogLabel(item))}</option>`).join('');const title=langText('Strateginiai ryšiai (tėvinės gairės)','Strategic links (parent guidelines)');const description=langText('Siekite šios institucijos tėvines gaires tarp skirtingų strategijų.','Connect this institution\'s parent guidelines across different strategies.');const sourcePlaceholder=langText('Pasirinkite šaltinio tėvinę gairę','Select source parent guideline');const targetPlaceholder=langText('Pasirinkite tikslo tėvinę gairę','Select target parent guideline');const createLabel=langText('Sukurti ryšį','Create link');const minGuidelinesMessage=langText('Reikia bent dviejų tėvinių gairių, kad būtų galima kurti ryšius.','At least two parent guidelines are required to create links.');const crossScope=langText('Tarpstrateginis','Cross-strategy');const sameScope=langText('Toje pačioje strategijoje','Within same strategy');const openGuidelineLabel=langText('Atidaryti gairę','Open guideline');const removeLinkLabel=langText('Pašalinti ryšį','Remove link');const noLinksLabel=langText('Ryšių dar nėra.','No links yet.');return `<section class="card" data-admin-section="strategic-links" style="margin-bottom:16px;"><div class="header-row"><strong>${title}</strong><span class="tag">${rows.length}</span></div><p class="prompt" style="margin-top:8px;">${description}</p><form id="createGuidelineLinkForm" class="admin-add-form"><div class="form-row"><select name="sourceGuidelineId" required ${state.busy||!hasEnoughGuidelines?'disabled':''}><option value="">${sourcePlaceholder}</option>${guidelineOptions}</select><select name="targetGuidelineId" required ${state.busy||!hasEnoughGuidelines?'disabled':''}><option value="">${targetPlaceholder}</option>${guidelineOptions}</select></div><button class="btn btn-primary" type="submit" ${state.busy||!hasEnoughGuidelines?'disabled':''}>${createLabel}</button></form>${hasEnoughGuidelines?'':`<p class="prompt" style="margin-top:8px;">${minGuidelinesMessage}</p>`}<ul class="mini-list" style="margin-top:10px;">${rows.length?rows.map(row=>{const href=buildGuidelineOpenHref(state.institutionSlug,row.targetStrategySlug,row.targetGuidelineId);const scope=row.isCrossStrategy?crossScope:sameScope;return `<li><div class="header-row" style="gap:8px;align-items:flex-start;"><div><strong>${escapeHtml(row.sourceGuidelineTitle)}</strong><p class="prompt" style="margin:4px 0 0;">${escapeHtml(row.sourceStrategyTitle)} → ${escapeHtml(row.targetStrategyTitle)}</p><p class="prompt" style="margin:4px 0 0;">→ ${escapeHtml(row.targetGuidelineTitle)}</p></div><div class="header-stack" style="align-items:flex-end;"><span class="tag">${escapeHtml(scope)}</span><span class="tag">${escapeHtml(formatDateTime(row.createdAt))}</span><div class="inline-form"><a class="btn btn-ghost" href="${escapeHtml(href)}">${openGuidelineLabel}</a><button class="btn btn-ghost" type="button" data-action="delete-guideline-link" data-link-id="${escapeHtml(row.id)}" ${state.busy?'disabled':''}>${removeLinkLabel}</button></div></div></div></li>`;}).join(''):`<li>${noLinksLabel}</li>`}</ul></section>`;}

function renderLogin(){const back=IS_EMBEDDED_ADMIN?'':`<p class="prompt" style="margin-top:12px;">Narys? Grįžkite į viešą puslapį: <a href="/index.html?institution=${encodeURIComponent(state.institutionSlug)}">index</a></p>`;root.innerHTML=`<section class="card" style="max-width:560px;margin:30px auto;"><h2 style="font-family:'Fraunces',serif;">Admin prisijungimas</h2><p class="prompt">Prisijunkite kaip institucijos administratorius.</p><p class="prompt">Institucija: <strong>${escapeHtml(state.institutionSlug)}</strong></p><div id="loginError" class="error" style="display:none;"></div><form id="adminLoginForm" class="login-form"><input type="text" name="email" placeholder="El. paštas" required /><input type="password" name="password" placeholder="Slaptažodis" required /><button type="submit" class="btn btn-primary">Prisijungti</button></form>${back}</section>`;const form=document.getElementById('adminLoginForm');const loginError=document.getElementById('loginError');form.addEventListener('submit',async(e)=>{e.preventDefault();const fd=new FormData(form);const email=String(fd.get('email')||'').trim();const password=String(fd.get('password')||'');if(!email||!password)return;try{const payload=await api('/api/v1/auth/login',{method:'POST',auth:false,body:{email,password,institutionSlug:state.institutionSlug}});setSession(payload);await bootstrap();}catch(error){const message=toUserMessage(error);loginError.style.display='block';loginError.textContent=message;notifyError(message);}});}
function flatComments(items,kind){const out=[];(items||[]).forEach(item=>{const comments=Array.isArray(item.comments)?item.comments:[];comments.forEach(c=>out.push({...c,kind,entityId:item.id,entityTitle:item.title||'-'}));});return out;}

function renderCardCommentModeration(comments,kind){
  const safeComments=Array.isArray(comments)?comments:[];
  const title=kind==='initiative'?'Komentarų moderavimas (iniciatyva)':'Komentarų moderavimas (gairė)';
  if(!safeComments.length)return `<section class="admin-comment-box"><div class="header-row"><strong>${title}</strong><span class="tag">0</span></div><p class="prompt">Komentarų dar nėra.</p></section>`;
  return `<section class="admin-comment-box"><div class="header-row"><strong>${title}</strong><span class="tag">${safeComments.length}</span></div><ul class="mini-list admin-comment-list">${safeComments.map(comment=>{const st=String(comment?.status||'visible').toLowerCase()==='hidden'?'hidden':'visible';const next=st==='hidden'?'visible':'hidden';const txt=st==='hidden'?'Rodyti':'Slėpti';const author=String(comment?.authorName||comment?.authorEmail||'Nežinomas autorius').trim();return `<li class="admin-comment-item ${st==='hidden'?'is-hidden':''}"><div class="admin-global-comment-head"><span class="tag">${escapeHtml(st)}</span><span class="tag">${escapeHtml(formatDateTime(comment?.createdAt))}</span></div><div class="admin-comment-body">${escapeHtml(comment?.body||'')}</div><div class="admin-comment-meta">${escapeHtml(author)}</div><div class="admin-comment-actions"><button type="button" class="btn btn-ghost comment-status-btn" data-comment-kind="${kind}" data-comment-id="${escapeHtml(comment?.id)}" data-next-status="${next}" ${state.busy?'disabled':''}>${txt}</button></div></li>`;}).join('')}</ul></section>`;
}
function renderCardVoteDetails(votes){
  const safeVotes=Array.isArray(votes)?votes:[];
  if(!safeVotes.length)return `<section class="admin-vote-box"><div class="header-row"><strong>Balsų detalizacija</strong><span class="tag">0</span></div><p class="prompt">Balsų dar nėra.</p></section>`;
  return `<section class="admin-vote-box"><div class="header-row"><strong>Balsų detalizacija</strong><span class="tag">${safeVotes.length}</span></div><ul class="mini-list admin-vote-list">${safeVotes.map(vote=>{const voter=String(vote?.voterName||vote?.voterEmail||'Nežinomas vartotojas').trim();return `<li><div class="header-row"><strong>${escapeHtml(voter)}</strong><span class="tag">Balas: ${Number(vote?.score||0)}</span></div><p class="prompt" style="margin:4px 0 0;">Atnaujinta: ${escapeHtml(formatDateTime(vote?.updatedAt))}</p></li>`;}).join('')}</ul></section>`;
}
function renderGuidelineCards(){
  return state.guidelines.map(g=>{const relation=String(g.relationType||'orphan');const comments=Array.isArray(g.comments)?g.comments:[];const parentOptions=state.guidelines.filter(c=>c.id!==g.id&&c.relationType==='parent').map(c=>`<option value="${escapeHtml(c.id)}" ${c.id===g.parentGuidelineId?'selected':''}>${escapeHtml(c.title)}</option>`).join('');return `<article class="card ${g.status==='active'?'':'admin-panel'}"><form class="admin-guideline-form admin-edit-form" data-id="${escapeHtml(g.id)}"><input class="admin-edit-title" type="text" name="title" value="${escapeHtml(g.title)}" required ${state.busy?'disabled':''}/><textarea class="admin-edit-description" name="description" placeholder="Aprašymas" ${state.busy?'disabled':''}>${escapeHtml(g.description||'')}</textarea><div class="admin-edit-grid"><select name="status" ${state.busy?'disabled':''}>${['active','disabled','merged','hidden'].map(i=>`<option value="${i}" ${i===g.status?'selected':''}>${i}</option>`).join('')}</select><select name="relationType" ${state.busy?'disabled':''}><option value="orphan" ${relation==='orphan'?'selected':''}>Našlaitė</option><option value="parent" ${relation==='parent'?'selected':''}>Tėvinė</option><option value="child" ${relation==='child'?'selected':''}>Vaikinė</option></select><select name="parentGuidelineId" ${state.busy?'disabled':''} ${relation==='child'?'':'disabled'}><option value="">Pasirinkite tėvinę gairę</option>${parentOptions}</select></div><div class="admin-edit-actions"><button class="btn btn-primary" type="submit" ${state.busy?'disabled':''}>Išsaugoti</button><button class="btn btn-danger guideline-delete-btn" type="button" data-guideline-id="${escapeHtml(g.id)}" data-guideline-title="${escapeHtml(g.title)}" ${state.busy?'disabled':''}>Ištrinti</button></div><div class="header-stack"><span class="tag">Komentarai: ${comments.length}</span><span class="tag">Ryšys: ${escapeHtml(relation)}</span></div>${renderCardCommentModeration(comments,'guideline')}</form></article>`;}).join('');
}
function renderInitiativeCards(){
  return state.initiatives.map(i=>{const selected=Array.isArray(i.guidelineIds)?i.guidelineIds:(Array.isArray(i.guidelineLinks)?i.guidelineLinks.map(x=>x.guidelineId):[]);const comments=Array.isArray(i.comments)?i.comments:[];const votes=Array.isArray(i.votes)?i.votes:[];const keywordValue=keywordInputValue(i.keywords);return `<article class="card ${i.status==='active'?'':'admin-panel'}"><form class="admin-initiative-form admin-edit-form" data-id="${escapeHtml(i.id)}"><input class="admin-edit-title" type="text" name="title" value="${escapeHtml(i.title)}" required ${state.busy?'disabled':''}/><textarea class="admin-edit-description" name="description" placeholder="Aprašymas" ${state.busy?'disabled':''}>${escapeHtml(i.description||'')}</textarea><label class="prompt admin-edit-label">Raktažodžiai</label><input type="text" name="keywords" value="${escapeHtml(keywordValue)}" placeholder="Pvz. Saugumas, DI, Duomenys" ${state.busy?'disabled':''}/><p class="prompt" style="margin:6px 0 10px;">Atskirkite kableliais. Raktažodžiai naudojami iniciatyvų sąrašo ir žemėlapio filtrams.</p><div class="admin-edit-grid admin-edit-grid-initiative"><select name="status" ${state.busy?'disabled':''}>${['active','disabled','merged','hidden'].map(s=>`<option value="${s}" ${s===i.status?'selected':''}>${s}</option>`).join('')}</select></div><label class="prompt admin-edit-label">Priskirtos gairės (bent 1)</label><div class="guideline-checkbox-panel">${guidelineCheckboxes(selected,'guidelineIds',state.busy)}</div><div class="admin-edit-actions"><button class="btn btn-primary" type="submit" ${state.busy?'disabled':''}>Išsaugoti</button><button class="btn btn-danger initiative-delete-btn" type="button" data-initiative-id="${escapeHtml(i.id)}" data-initiative-title="${escapeHtml(i.title)}" ${state.busy?'disabled':''}>Ištrinti</button></div><div class="header-stack"><span class="tag">Balas: ${Number(i.totalScore||0)}</span><span class="tag">Komentarai: ${comments.length}</span></div>${renderCardVoteDetails(votes)}${renderCardCommentModeration(comments,'initiative')}</form></article>`;}).join('');
}
function proposalById(proposalId){const id=String(proposalId||'').trim();if(!id)return null;return (Array.isArray(state.pendingProposals)?state.pendingProposals:[]).find(item=>String(item?.id||'').trim()===id)||null;}
function proposalKindLabel(kind){const normalized=String(kind||'').trim().toLowerCase();if(normalized==='guideline')return langText('Gairė','Guideline');if(normalized==='initiative')return langText('Iniciatyva','Initiative');return normalized||'-';}
function buildPendingProposalHref(proposal){const kind=String(proposal?.entityKind||'').trim().toLowerCase();const proposalId=String(proposal?.id||'').trim();const institutionSlug=normalizeSlug(state.institutionSlug);const strategySlug=normalizeSlug(state.strategySlug);if(!institutionSlug||!strategySlug||!proposalId||!['guideline','initiative'].includes(kind))return'';const params=new URLSearchParams();params.set('lang',resolveEmbedLanguage());return `/institution/${encodeURIComponent(institutionSlug)}/strategy/${encodeURIComponent(strategySlug)}/${kind}/${encodeURIComponent(proposalId)}?${params.toString()}`;}
function renderPendingProposalCards(){const pending=Array.isArray(state.pendingProposals)?state.pendingProposals:[];if(!pending.length)return `<div class="card guideline-empty"><strong>${escapeHtml(langText('Laukiančių pasiūlymų nėra','No pending proposals'))}</strong></div>`;return pending.map(item=>{const href=buildPendingProposalHref(item);const kind=String(item?.entityKind||'').trim().toLowerCase();const relationType=String(item?.relationType||'').trim().toLowerCase();const relationTag=kind==='guideline'&&relationType?`<span class="tag">${escapeHtml(langText('Ryšys','Relation'))}: ${escapeHtml(relationType)}</span>`:'';return `<article class="card history-entry-card history-status-pending"><div class="header-row"><strong>${escapeHtml(String(item?.title||item?.id||'-').trim()||'-')}</strong><div class="header-stack"><span class="tag">${escapeHtml(proposalKindLabel(kind))}</span><span class="tag tag-main">${escapeHtml(langText('Laukia tvirtinimo','Pending review'))}</span></div></div><p>${escapeHtml(String(item?.description||'').trim()||langText('Aprašymas nepateiktas.','Description not provided.'))}</p><div class="header-stack" style="margin-top:8px;"><span class="tag">${escapeHtml(langText('Pateikė','Requested by'))}: ${escapeHtml(String(item?.requestedByName||item?.requestedBy||'-').trim()||'-')}</span><span class="tag">${escapeHtml(langText('Data','Date'))}: ${escapeHtml(formatDateTime(item?.requestedAt))}</span>${relationTag}${item?.commentCount?`<span class="tag">${escapeHtml(langText('Komentarai','Comments'))}: ${Number(item.commentCount||0)}</span>`:''}</div><div class="header-stack" style="margin-top:10px;">${href?`<a class="btn btn-ghost" href="${escapeHtml(href)}">${escapeHtml(langText('Atidaryti kortelę','Open card'))}</a>`:''}<button type="button" class="btn btn-primary" data-action="open-pending-review" data-proposal-id="${escapeHtml(item?.id)}" ${state.busy?'disabled':''}>${escapeHtml(langText('Peržiūrėti','Review'))}</button></div></article>`;}).join('');}
function renderPendingReviewModal(){const proposal=proposalById(state.pendingReviewProposalId);if(!proposal)return'';const kind=String(proposal.entityKind||'').trim().toLowerCase();const relation=String(proposal.relationType||'orphan').trim().toLowerCase()||'orphan';const parentGuidelineId=String(proposal.parentGuidelineId||'').trim();const guidelineIds=Array.isArray(proposal.guidelineIds)?proposal.guidelineIds:[];const parentOptions=state.guidelines.filter(item=>item.id!==proposal.id&&item.relationType==='parent').map(item=>`<option value="${escapeHtml(item.id)}" ${item.id===parentGuidelineId?'selected':''}>${escapeHtml(item.title||item.id)}</option>`).join('');return `<div class="modal-overlay" id="pendingProposalReviewOverlay"><div class="modal-card"><div class="header-row"><h3 style="margin:0;">${escapeHtml(langText('Pasiūlymo peržiūra','Proposal review'))}</h3><button type="button" class="btn btn-ghost" data-action="close-pending-review-modal">${escapeHtml(langText('Uždaryti','Close'))}</button></div><form id="pendingProposalDecisionForm" data-proposal-id="${escapeHtml(proposal.id)}" data-proposal-kind="${escapeHtml(kind)}"><div class="form-row"><label class="prompt" for="pendingProposalDecisionInput">${escapeHtml(langText('Sprendimas','Decision'))}</label><select id="pendingProposalDecisionInput" name="decision" ${state.busy?'disabled':''}><option value="approved">${escapeHtml(langText('Patvirtinti','Approve'))}</option><option value="approved_with_changes">${escapeHtml(langText('Patvirtinti su pakeitimais','Approve with changes'))}</option><option value="rejected">${escapeHtml(langText('Atmesti','Reject'))}</option></select></div><div class="pending-proposal-patch-fields" id="pendingProposalPatchFields" hidden><div class="form-row"><label class="prompt" for="pendingProposalTitleInput">${escapeHtml(langText('Pavadinimas','Title'))}</label><input id="pendingProposalTitleInput" name="title" type="text" value="${escapeHtml(String(proposal.title||'').trim())}" ${state.busy?'disabled':''}/></div><div class="form-row"><label class="prompt" for="pendingProposalDescriptionInput">${escapeHtml(langText('Aprašymas','Description'))}</label><textarea id="pendingProposalDescriptionInput" name="description" class="admin-edit-description" ${state.busy?'disabled':''}>${escapeHtml(String(proposal.description||'').trim())}</textarea></div>${kind==='guideline'?`<div class="form-row"><label class="prompt" for="pendingProposalRelationInput">${escapeHtml(langText('Ryšio tipas','Relation type'))}</label><select id="pendingProposalRelationInput" name="relationType" ${state.busy?'disabled':''}><option value="orphan" ${relation==='orphan'?'selected':''}>orphan</option><option value="parent" ${relation==='parent'?'selected':''}>parent</option><option value="child" ${relation==='child'?'selected':''}>child</option></select></div><div class="form-row"><label class="prompt" for="pendingProposalParentGuidelineInput">${escapeHtml(langText('Tėvinė gairė','Parent guideline'))}</label><select id="pendingProposalParentGuidelineInput" name="parentGuidelineId" ${state.busy?'disabled':''}><option value="">${escapeHtml(langText('Pasirinkite tėvinę gairę','Select parent guideline'))}</option>${parentOptions}</select></div>`:''}${kind==='initiative'?`<div class="form-row"><label class="prompt">${escapeHtml(langText('Priskirtos gairės','Linked guidelines'))}</label><div class="guideline-checkbox-panel">${guidelineCheckboxes(guidelineIds,'proposalGuidelineIds',state.busy)}</div></div>`:''}</div><div class="form-row"><label class="prompt" for="pendingProposalReviewNoteInput">${escapeHtml(langText('Pastaba','Note'))}</label><textarea id="pendingProposalReviewNoteInput" name="reviewNote" class="admin-edit-description" placeholder="${escapeHtml(langText('Paaiškinkite sprendimą','Explain the decision'))}" ${state.busy?'disabled':''}></textarea></div><div class="header-stack" style="margin-top:12px;"><button type="submit" class="btn btn-primary" ${state.busy?'disabled':''}>${escapeHtml(langText('Išsaugoti sprendimą','Save decision'))}</button><button type="button" class="btn btn-ghost" data-action="close-pending-review-modal">${escapeHtml(langText('Atšaukti','Cancel'))}</button></div></form></div></div>`;}
function syncPendingReviewPatchVisibility(){const select=document.getElementById('pendingProposalDecisionInput');const patchFields=document.getElementById('pendingProposalPatchFields');if(!(select instanceof HTMLSelectElement)||!(patchFields instanceof HTMLElement))return;const show=String(select.value||'').trim().toLowerCase()==='approved_with_changes';patchFields.hidden=!show;const parentSelect=document.getElementById('pendingProposalParentGuidelineInput');const relationSelect=document.getElementById('pendingProposalRelationInput');if(parentSelect instanceof HTMLSelectElement&&relationSelect instanceof HTMLSelectElement){const relation=String(relationSelect.value||'orphan').trim().toLowerCase();const needsParent=show&&relation==='child';parentSelect.disabled=state.busy||!needsParent;if(!needsParent)parentSelect.value='';}}
function activeAdminGuidelines(){return(Array.isArray(state.guidelines)?state.guidelines:[]).filter(item=>String(item?.status||'active').trim().toLowerCase()==='active');}
function activeAdminInitiatives(){return(Array.isArray(state.initiatives)?state.initiatives:[]).filter(item=>String(item?.status||'active').trim().toLowerCase()==='active');}
function localizeItPlanAttributeLabels(value){const labels={goal:'Tikslas',objective:'Tikslas',description:'Aprašymas',owner:'Atsakingas',status:'Būsena',priority:'Prioritetas',measure:'Priemonė',deadline:'Terminas',timeline:'Laikotarpis',result:'Rezultatas',cost:'Kaštai',funding:'Finansavimas'};let text=String(value||'');Object.entries(labels).forEach(([source,target])=>{const escaped=source.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');text=text.replace(new RegExp(`(<(?:strong|b)[^>]*>\\s*)${escaped}\\s*:(\\s*<\\/(?:strong|b)>)`,'gi'),`$1${target}:$2`);text=text.replace(new RegExp(`(^|[\\s\\n])${escaped}\\s*:`,'gi'),`$1${target}:`);});return text;}
function compactPlanText(value,max=900){return localizeItPlanAttributeLabels(value).replace(/\s+/g,' ').trim();}
function planSentence(value,fallback){const text=compactPlanText(value,360);return text||fallback;}
function markdownCell(value){return stripItPlanHtml(value).replace(/\|/g,'/').replace(/\s+/g,' ').trim();}
function stripItPlanHtml(value){const host=document.createElement('div');const withBreaks=String(value||'').replace(/<br\s*\/?>/gi,'\n').replace(/<\/(div|p|li|tr)>/gi,'\n');host.innerHTML=withBreaks;return String(host.textContent||'').replace(/\u00a0/g,' ').replace(/\n{3,}/g,'\n\n').trim();}
function renderItPlanRichHtml(value){return escapeHtml(value).replace(/&lt;(strong|b|em|i)(?:\s.*?)?&gt;/gi,'<$1>').replace(/&lt;\/(strong|b|em|i)&gt;/gi,'</$1>').replace(/&lt;br\s*\/?&gt;/gi,'<br>');}
const IT_PLAN_ABBREVIATION_EXPLANATIONS={
  API:'Aplikacijų programavimo sąsaja',
  CPU:'Centrinis procesorius',
  DI:'Dirbtinis intelektas',
  DR:'Atkūrimas po sutrikimo / veiklos tęstinumo užtikrinimas',
  DTMF:'Daugiadažnis toninis rinkimas',
  EDR:'Galinių įrenginių aptikimo ir reagavimo priemonė',
  ES:'Europos Sąjunga',
  ESCO:'Europos įgūdžių, kompetencijų, kvalifikacijų ir profesijų klasifikatorius',
  HDD:'Duomenų saugykla / kietasis diskas',
  IDS:'Įsilaužimų aptikimo sistema',
  IPS:'Įsilaužimų prevencijos sistema',
  IS:'Informacinė sistema',
  IT:'Informacinės technologijos',
  KDV:'Kompiuterizuota darbo vieta',
  LDV:'Laisva darbo vieta',
  LR:'Lietuvos Respublika',
  RAM:'Operatyvioji atmintis',
  RISR:'Registrų ir informacinių sistemų registras',
  SaaS:'Programinė įranga kaip paslauga',
  SIEM:'Saugumo informacijos ir įvykių valdymo sistema',
  UZT:'Užimtumo tarnyba',
  'UŽT':'Užimtumo tarnyba',
  VDC:'Valstybės duomenų centras',
  VSSA:'Valstybės skaitmeninių sprendimų agentūra',
  AICCA:'Artificial Intelligence Career Coaching Assistant'
};
const IT_PLAN_ABBREVIATION_STOP_WORDS=new Set(['KAS','KAD','KUR','NES','BET','AR','IR','TIK','TAIP','JEI']);
function normalizeItPlanAbbreviation(value){return String(value||'').trim().replace(/^[^\p{L}\p{N}]+|[^\p{L}\p{N}]+$/gu,'');}
function cleanItPlanDefinition(value){
  return compactPlanText(value,220).replace(/^(pvz\.?|t\. y\.|tai yra)\s*[,;:-]?\s*/i,'').replace(/[.,;:\s-]+$/g,'').trim();
}
function addItPlanDefinition(definitions,abbr,explanation){
  const key=normalizeItPlanAbbreviation(abbr);
  const value=cleanItPlanDefinition(explanation);
  if(!isItPlanAbbreviation(key)||IT_PLAN_ABBREVIATION_STOP_WORDS.has(key))return;
  if(!value||value.length<3)return;
  const existing=String(definitions.get(key)||'').trim();
  if(!existing||/nepaaiškinta|patikslinti/i.test(existing)||value.length>existing.length)definitions.set(key,value);
}
function isItPlanAbbreviation(value){
  const text=normalizeItPlanAbbreviation(value);
  if(!text||text.length<2||text.length>12)return false;
  if(IT_PLAN_ABBREVIATION_STOP_WORDS.has(text))return false;
  if(IT_PLAN_ABBREVIATION_EXPLANATIONS[text])return true;
  return /^[A-ZĄČĘĖĮŠŲŪŽ0-9]{2,12}$/.test(text)&&/[A-ZĄČĘĖĮŠŲŪŽ]/.test(text);
}
function buildItPlanTermsText(guidelines,initiatives){
  const sourceText=stripItPlanHtml([...(guidelines||[]),...(initiatives||[])].map(item=>`${item?.title||''} ${item?.description||''}`).join('\n')).replace(/\s+/g,' ').trim();
  const definitions=new Map();
  const parenthetical=/([A-ZĄČĘĖĮŠŲŪŽa-ząčęėįšųūž][^()]{4,180}?)\s*\(([A-ZĄČĘĖĮŠŲŪŽ0-9]{2,12})\)/g;
  let match;
  while((match=parenthetical.exec(sourceText))){
    addItPlanDefinition(definitions,match[2],match[1]);
  }
  const acronymBeforeDefinition=/([A-ZĄČĘĖĮŠŲŪŽ0-9]{2,12})\s*\(([^()]{4,240})\)/g;
  while((match=acronymBeforeDefinition.exec(sourceText))){
    addItPlanDefinition(definitions,match[1],match[2]);
  }
  const separatorDefinition=/(^|[\s,;])([A-ZĄČĘĖĮŠŲŪŽ0-9]{2,12})\s*(?:-|–|—|:)\s*([^.;\n]{4,220})/gu;
  while((match=separatorDefinition.exec(sourceText))){
    addItPlanDefinition(definitions,match[2],match[3]);
  }
  const meansDefinition=/(^|[\s,;])([A-ZĄČĘĖĮŠŲŪŽ0-9]{2,12})\s+(?:reiškia|yra)\s+([^.;\n]{4,220})/giu;
  while((match=meansDefinition.exec(sourceText))){
    addItPlanDefinition(definitions,match[2],match[3]);
  }
  Object.keys(IT_PLAN_ABBREVIATION_EXPLANATIONS).forEach(abbr=>{
    const escaped=abbr.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
    const pattern=new RegExp(`(^|[^\\p{L}\\p{N}])${escaped}(?=$|[^\\p{L}\\p{N}])`,'u');
    if(pattern.test(sourceText)&&!definitions.has(abbr))definitions.set(abbr,IT_PLAN_ABBREVIATION_EXPLANATIONS[abbr]);
  });
  const acronymPattern=/(^|[^\p{L}\p{N}])([A-ZĄČĘĖĮŠŲŪŽ]{2,12})(?=$|[^\p{L}\p{N}])/gu;
  while((match=acronymPattern.exec(sourceText))){
    const abbr=normalizeItPlanAbbreviation(match[2]);
    if(!abbr||/^\d+$/.test(abbr))continue;
    if(!definitions.has(abbr)&&!IT_PLAN_ABBREVIATION_STOP_WORDS.has(abbr))definitions.set(abbr,IT_PLAN_ABBREVIATION_EXPLANATIONS[abbr]||'Strategijoje reikšmė nepaaiškinta.');
  }
  const rows=[...definitions.entries()].sort((a,b)=>a[0].localeCompare(b[0],'lt'));
  if(!rows.length)return'Gairėse ir iniciatyvose aiškių trumpinių neatpažinta. Jeigu plane naudojami papildomi sutrumpinimai, juos reikia įrašyti rankiniu būdu.';
  return rows.map(([abbr,explanation])=>`${abbr} - ${explanation}`).join('\n');
}
function itPlanGuidelineTitlesForInitiative(initiative){const linked=Array.isArray(initiative?.guidelineLinks)?initiative.guidelineLinks:[];const ids=Array.isArray(initiative?.guidelineIds)?initiative.guidelineIds:linked.map(item=>item.guidelineId);const byId=new Map(activeAdminGuidelines().map(item=>[String(item.id),item]));const titles=[];ids.forEach(id=>{const guideline=byId.get(String(id));if(guideline?.title)titles.push(String(guideline.title).trim());});linked.forEach(item=>{const title=String(item?.guidelineTitle||item?.title||'').trim();if(title&&!titles.includes(title))titles.push(title);});return titles;}
function itPlanInitiativeTimeline(initiative){const date=String(initiative?.implementationDate||initiative?.implementation_target_date||'').trim();return date||'Reikia patikslinti pagal strategijos turinį.';}
function inferItPlanChangeType(initiative){const text=`${initiative?.title||''} ${initiative?.description||''}`.toLowerCase();if(/likvid|atsisak|nebeteik/.test(text))return'Likvidavimas';if(/migrav|perkėl|perkel|debes|valstybės duomenų centr/.test(text))return'Pertvarkymas';if(/nauj|sukūr|sukur|dieg|įdieg|idieg/.test(text))return'Sukūrimas';if(/atnaujin|moderniz|tobulin|plėtr|plet/.test(text))return'Atnaujinimas';return'Atnaujinimas / plėtra';}
function initiativeMatchesPlanTopic(initiative,pattern){const text=`${initiative?.title||''} ${initiative?.description||''}`.toLowerCase();return pattern.test(text);}
function itPlanRowsForInitiatives(items){return items.map(item=>{const linked=itPlanGuidelineTitlesForInitiative(item);return[`${item.title||'-'}, ${inferItPlanChangeType(item)}`,planSentence(item.description,'Reikia papildyti planuojamo pokyčio aprašymą.'),itPlanInitiativeTimeline(item),linked.length?linked.join('; '):'Reikia patikslinti sąsają su plėtros tikslais.'];});}
function itPlanSectionTitle(block){const number=String(block?.number||'').trim();const title=String(block?.title||'').trim();return number?`${number} ${title}`:title;}
function itPlanNarrativeItems(items,limit=6){return items.slice(0,limit).map(item=>{const title=String(item?.title||'').trim();const description=compactPlanText(item?.description||'',240);return title&&description?`${title} - ${description}`:title||description;}).filter(Boolean);}
function itPlanSourceItems(items,limit=8){const seen=new Set();return(Array.isArray(items)?items:[]).map(item=>String(item?.title||item?.id||'').trim()).filter(title=>{if(!title||seen.has(title))return false;seen.add(title);return true;}).slice(0,limit);}
function itPlanConfidenceLabel(block){const status=String(block?.status||'review').trim().toLowerCase();if(status==='ready')return'aukštas';if(status==='missing')return'žemas';return'vidutinis';}
function itPlanEvidenceItems(block){const items=[];const sourceCount=Array.isArray(block?.sourceItems)?block.sourceItems.length:0;const rowCount=Array.isArray(block?.table?.rows)?block.table.rows.length:0;if(sourceCount)items.push(`Naudota šaltinių: ${sourceCount}`);if(rowCount)items.push(`Sugeneruota lentelės eilučių: ${rowCount}`);if(Array.isArray(block?.missingFields)&&block.missingFields.length)items.push(`Papildytini laukai: ${block.missingFields.length}`);if(!items.length)items.push('Pagrindas: VSSA šablono struktūra ir strategijos duomenų peržiūra');return items;}
function itPlanBlockIssues(block){const issues=[];const status=String(block?.status||'review').trim().toLowerCase();const text=itPlanBlockContentText(block);if(status==='missing')issues.push('Skirsniui trūksta duomenų, kurių digistrategy.eu nekaupia.');if(/Reikia patikslinti|Reikia papildyti|Reikia pridėti|neatpažinta|nepaaiškinta/i.test(text))issues.push('Tekste liko vietų, kurias reikia patikslinti arba papildyti.');if(/trumpinio reikšmę|reikšmė nepaaiškinta/i.test(text))issues.push('Yra trumpinių be patvirtintos reikšmės.');if(Array.isArray(block?.table?.rows)&&block.table.rows.length===0)issues.push('Lentelėje nėra sugeneruotų įrašų.');return[...new Set(issues)];}
function itPlanDraftIssues(blocks){return(Array.isArray(blocks)?blocks:[]).flatMap(block=>itPlanBlockIssues(block).map(issue=>({block,issue})));}
